package com.chatq.keyboardtests;
import android.content.*;import android.database.sqlite.*;import java.io.*;import java.lang.reflect.*;import org.json.*;
final class FeatureChecks {
 static int checks=0;static void expect(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;}
 static void reject(Method m,Object o,Object...a)throws Exception{try{m.invoke(o,a);throw new AssertionError("expected rejection");}catch(InvocationTargetException e){checks++;}}
 static int run(Context original)throws Exception{
  final File dir=new File(original.getCacheDir(),"chatq-feature114-tests");dir.mkdirs();
  Context context=new ContextWrapper(original){public SharedPreferences getSharedPreferences(String n,int mode){return original.getSharedPreferences("feature114_"+n,mode);}public File getDatabasePath(String n){return new File(dir,n);}public File getCacheDir(){return dir;}};
  SQLiteDatabase.deleteDatabase(context.getDatabasePath("chatq-generations.db"));context.getSharedPreferences("chatq_keyboard",0).edit().clear().commit();context.getSharedPreferences("chatq_sync_v1",0).edit().clear().commit();
  ClassLoader loader=original.getClassLoader();Class<?> t=loader.loadClass("expo.modules.chatqkeyboard.GenerationStore"),vaultType=loader.loadClass("expo.modules.chatqkeyboard.SyncVault");Object store=t.getConstructor(Context.class).newInstance(context),vault=vaultType.getConstructor(Context.class).newInstance(context);
  Method save=t.getMethod("saveChat",String.class),get=t.getMethod("getChat",String.class),merge=t.getMethod("mergeSyncChats",String.class,String.class),encrypt=vaultType.getMethod("encrypt",String.class,String.class),decrypt=vaultType.getMethod("decrypt",String.class,String.class),remember=vaultType.getMethod("save",String.class,String.class),load=vaultType.getMethod("load",String.class),forget=vaultType.getMethod("forget");
  try{
   JSONObject chat=ConversationChecks.chat("feature114-original");chat.put("parent",new JSONObject().put("sessionId","parent-test").put("turnId","old-turn"));JSONObject turn=chat.getJSONArray("turns").getJSONObject(0);turn.put("alternatives",new JSONArray().put(new JSONObject().put("answer","旧版回答").put("at",1700000000000L).put("personaName","助手")));turn.put("attachments",new JSONArray().put(new JSONObject().put("id","file1").put("name","资料.md").put("mime","text/plain").put("content","附件正文")));
   expect((Boolean)save.invoke(store,chat.toString()),"save versions/attachments/branch");expect(new JSONObject((String)get.invoke(store,chat.getString("id"))).getJSONArray("turns").getJSONObject(0).getJSONArray("alternatives").length()==1,"native round-trip versions");
   JSONObject backup=(JSONObject)t.getMethod("export").invoke(store);expect(backup.getJSONArray("chats").getJSONObject(0).getJSONArray("turns").getJSONObject(0).getJSONArray("attachments").length()==1,"encrypted backup payload includes attachments");
   JSONArray before=new JSONArray().put(new JSONObject((String)get.invoke(store,chat.getString("id"))));JSONObject newer=new JSONObject(chat.toString()).put("draft","另一设备的更改").put("updatedAt",1700000000200L);merge.invoke(store,before.toString(),new JSONArray().put(newer).toString());expect(new JSONObject((String)get.invoke(store,chat.getString("id"))).getString("draft").equals("另一设备的更改"),"atomic sync replaces exact captured revision");
   reject(merge,store,before.toString(),before.toString());expect(new JSONObject((String)get.invoke(store,chat.getString("id"))).getString("draft").equals("另一设备的更改"),"stale merge preserves concurrent local change");reject(merge,store,new JSONArray().put(newer).toString(),"[]");
   t.getMethod("setEnabled",boolean.class).invoke(store,false);reject(merge,store,new JSONArray().put(newer).toString(),new JSONArray().put(newer).toString());t.getMethod("setEnabled",boolean.class).invoke(store,true);
   String code=(String)vaultType.getMethod("create").invoke(vault),other=(String)vaultType.getMethod("create").invoke(vault);expect(code.matches("CQ1\\.[a-f0-9]{32}\\.[a-f0-9]{64}")&&!code.equals(other),"secure random distinct recovery keys");String credentials=(String)vaultType.getMethod("credentials",String.class).invoke(vault,code);expect(!credentials.contains(code.split("\\.")[2])&&new JSONObject(credentials).getString("auth").length()==64,"wire authentication excludes encryption secret");
   remember.invoke(vault,code,"server-A");expect(load.invoke(vault,"server-A").equals(code)&&load.invoke(vault,"server-B")==null,"Keystore-wrapped key bound to connection");expect(!context.getSharedPreferences("chatq_sync_v1",0).getString("key","").contains(code),"stored preferences do not contain recovery key plaintext");
   String source="加密会话🙂",a=(String)encrypt.invoke(vault,source,code),b=(String)encrypt.invoke(vault,source,code);expect(!a.equals(b)&&!a.contains(source),"fresh salt and nonce encrypt every upload");expect(decrypt.invoke(vault,a,code).equals(source),"UTF-8 AES-GCM round trip");reject(decrypt,vault,a,other);JSONObject damaged=new JSONObject(a);damaged.put("data",damaged.getString("data").replaceFirst(".",damaged.getString("data").startsWith("A")?"B":"A"));reject(decrypt,vault,damaged.toString(),code);forget.invoke(vault);expect(load.invoke(vault,"server-A")==null,"disconnect forgets local key only");
   JSONObject bad=new JSONObject(chat.toString());bad.getJSONArray("turns").getJSONObject(0).getJSONArray("attachments").getJSONObject(0).put("content",new String(new char[12001]).replace('\0','x'));reject(save,store,bad.toString());
   JSONObject large=ConversationChecks.chat("feature114-large");JSONArray many=new JSONArray();String binary="data:image/jpeg;base64,"+new String(new char[690000]).replace('\0','A');for(int i=0;i<4;i++){JSONObject item=new JSONObject(large.getJSONArray("turns").getJSONObject(0).toString());item.put("id","large-"+i).put("attachments",new JSONArray().put(new JSONObject().put("id","img").put("name","image.jpg").put("mime","image/jpeg").put("content",binary)));many.put(item);}large.put("turns",many);save.invoke(store,large.toString());expect(((String)get.invoke(store,"feature114-large")).equals(large.toString()),"large attachment row bypasses 2MB CursorWindow without truncation");expect(new JSONArray((String)t.getMethod("listChats").invoke(store)).length()==2,"list remains readable with large row");expect(((JSONObject)t.getMethod("export").invoke(store)).getJSONArray("chats").length()==2,"backup includes large attachment-bearing row");
   return checks;
  }finally{((SQLiteOpenHelper)store).close();SQLiteDatabase.deleteDatabase(context.getDatabasePath("chatq-generations.db"));context.getSharedPreferences("chatq_keyboard",0).edit().clear().commit();context.getSharedPreferences("chatq_sync_v1",0).edit().clear().commit();}
 }
}
